<?php
require_once __DIR__ . '/../config/db.php';
require_once __DIR__ . '/../helpers/http.php';
function listRooms(): void { $pdo=getDb(); try{$s=$pdo->query('SELECT room_id,room_number,room_type,floor,status FROM Room ORDER BY room_number');jsonResponse(200,$s->fetchAll());}catch(Exception $e){error_log($e->getMessage());jsonResponse(500,['message'=>'Could not fetch rooms.']);} }
function listAdmissions(): void { $pdo=getDb(); try{$s=$pdo->query("SELECT a.admission_id,a.patient_id,p.name AS patient_name,a.room_id,r.room_number,r.room_type,a.doctor_id,d.name AS doctor_name,a.admission_date,a.discharge_date FROM Admission a JOIN Patient p ON a.patient_id=p.patient_id JOIN Room r ON a.room_id=r.room_id JOIN Doctor d ON a.doctor_id=d.doctor_id ORDER BY a.admission_date DESC");jsonResponse(200,$s->fetchAll());}catch(Exception $e){error_log($e->getMessage());jsonResponse(500,['message'=>'Could not fetch admissions.']);} }
function createAdmission(array $body): void {
 $pid=$body['patient_id']??null;$rid=$body['room_id']??null;$did=$body['doctor_id']??null;if(!$pid||!$rid||!$did)jsonResponse(400,['message'=>'patient_id, room_id and doctor_id are required.']);
 $pdo=getDb();try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT status FROM Room WHERE room_id=? FOR UPDATE");$s->execute([$rid]);$r=$s->fetch();if(!$r){$pdo->rollBack();jsonResponse(404,['message'=>'Room not found.']);}if($r['status']!=='Available'){ $pdo->rollBack();jsonResponse(409,['message'=>'Selected room is not available.']);}
 $s=$pdo->prepare('INSERT INTO Admission(patient_id,room_id,doctor_id) VALUES(?,?,?)');$s->execute([$pid,$rid,$did]);$s=$pdo->prepare("UPDATE Room SET status='Occupied' WHERE room_id=?");$s->execute([$rid]);$pdo->commit();jsonResponse(201,['admission_id'=>(int)$pdo->lastInsertId(),'message'=>'Patient admitted successfully.']);}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());jsonResponse(500,['message'=>'Could not admit patient.']);}}
function dischargeAdmission(int $id): void { $pdo=getDb();try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT room_id,discharge_date FROM Admission WHERE admission_id=? FOR UPDATE');$s->execute([$id]);$a=$s->fetch();if(!$a){$pdo->rollBack();jsonResponse(404,['message'=>'Admission not found.']);}if($a['discharge_date']){$pdo->rollBack();jsonResponse(409,['message'=>'Patient is already discharged.']);}$pdo->prepare('UPDATE Admission SET discharge_date=NOW() WHERE admission_id=?')->execute([$id]);$pdo->prepare("UPDATE Room SET status='Available' WHERE room_id=?")->execute([$a['room_id']]);$pdo->commit();jsonResponse(200,['message'=>'Patient discharged and room released.']);}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());jsonResponse(500,['message'=>'Could not discharge patient.']);}}
